import {watchPayment} from './payment-watch.mjs';
let checkoutWatch;
import {archiveCheckout,recoverCheckout} from './checkout-state.mjs';
const app=document.querySelector('#app');
let catalog,notices=[],publicReviews=[],view='browse';
const itemFor=id=>[...catalog.products,...(catalog.legacyProducts||[])].find(p=>p.id===id)||catalog.product;
const statuses=new Map();
async function loadStatus(p){try{const c=await api('/api/challenges',{id:p.receipt.id});const request={purchaseId:p.receipt.id,nonce:c.nonce};const key=await crypto.subtle.importKey('jwk',p.privateKey,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);const signature=b64(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,bytes(JSON.stringify(['veylo.status.v1',request.purchaseId,request.nonce]))));statuses.set(p.receipt.id,{...await api('/api/purchase-status',{request,signature}),checkedAt:new Date().toISOString()});}catch{statuses.set(p.receipt.id,{...statuses.get(p.receipt.id),unavailable:true});}}

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=s=>new TextEncoder().encode(s);
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const un64=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
const receiptPayload=r=>JSON.stringify([r.schema,r.id,r.product,r.version,r.amount,r.asset,r.purchaseKey,r.issuedAt,r.paymentMode,...(r.paymentMode==='testnet'?[r.payment]:[]),...(r.downloadPolicy?[r.downloadPolicy]:[]),...(r.delivery?[r.delivery]:[])]);
function passes(){try{return JSON.parse(localStorage.getItem('veylo.passes')||'[]');}catch{return [];}}
function keep(p){const list=passes().filter(x=>x.receipt.id!==p.receipt.id);list.push(p);localStorage.setItem('veylo.passes',JSON.stringify(list));}
async function api(url,data){const res=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const value=await res.json();if(!res.ok)throw Error(value.error||'Request failed.');return value;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6000);}
function bind(id,fn){document.getElementById(id)?.addEventListener('click',async e=>{e.preventDefault();const button=e.currentTarget;button.disabled=true;try{await fn();}catch(err){toast(err.message);}finally{button.disabled=false;}});}
function download(name,data,type='application/json'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function nav(){checkoutWatch?.stop();checkoutWatch=null;document.body.dataset.view=view;document.querySelector('#location').textContent=({buyer:'Your purchases',seller:'Seller console',browse:'Browse',history:'History',help:'How it works',product:'Product details'})[view]||'Checkout';for(const [id,v] of [['buyerNav','buyer'],['sellerNav','seller'],['browseNav','browse'],['historyNav','history'],['helpNav','help']])document.getElementById(id)?.classList.toggle('active',view===v);}
async function browse(category='All'){
 catalog=await api('/api/catalog');
 publicReviews=await api('/api/reviews');
 view='browse';nav();
 const categories=['All',...new Set(catalog.products.map(p=>p.category))];
 const selected=catalog.products.filter(p=>category==='All'||p.category===category);
 app.innerHTML=`<div class="heading browse-heading"><div><div class="eyebrow">THE COLLECTION</div><h1>Useful things. Yours to keep.</h1><p class="sub">Digital tools for your work, plans, and ideas.</p></div><div class="browse-actions">${localStorage.getItem('veylo.pending')?'<button class="btn" id="resumeCheckout">Resume checkout</button>':''}</div></div><div class="catalog-toolbar"><div class="catalog-filters">${categories.map(c=>`<button class="btn ${c===category?'primary':'quiet'}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><span class="product-count">${selected.length} ${selected.length===1?'product':'products'}</span></div><div class="catalog-grid">${selected.map(p=>`<article class="catalog-card"><div class="catalog-cover tone-${esc(p.tone)}">${productPreview(p)}</div><div class="panel-body"><span class="eyebrow">${esc(p.category)}</span><h3>${esc(p.name)}</h3>${ratingSummary(p.id)}<p class="muted">${esc(p.description)}</p><div class="catalog-bottom"><strong>${esc(p.price)} ${esc(p.asset)}</strong><button class="btn primary" id="get-${esc(p.id)}">View product</button></div><p class="note">${esc(p.seller)} · ${esc(p.format||"Text download")}</p></div></article>`).join('')}</div><p class="note">${catalog.paymentMode==='testnet'?'Zcash testnet storefront':'Payment simulation'}</p>${reviewsHTML()}`;
 bind('resumeCheckout',()=>checkout());
 for(const p of selected)bind('get-'+p.id,()=>productDetails(p.id));
 for(const b of app.querySelectorAll('[data-category]'))b.addEventListener('click',()=>browse(b.dataset.category));
}
async function buyer(){
 view='buyer';nav();notices=await api('/api/notices');const list=passes();await Promise.all(list.map(loadStatus));
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">PERSONAL LIBRARY</div><h1>Your purchases</h1><p class="sub">Your downloads, release updates, and refund requests.</p></div><div class="actions"><button class="btn quiet" id="sync">Refresh status</button><button class="btn" id="import">Restore purchase</button><button class="btn primary" id="browseProducts">Browse products</button></div><input id="file" type="file" accept="application/json,.json" class="hidden"></div><div class="layout"><section class="panel collection"><div class="panel-head"><h2>Collection</h2><span class="count">${list.length} ${list.length===1?'purchase':'purchases'}</span></div>${list.length?list.map(p=>purchaseHTML(p)).join(''):'<div class="empty"><h2>Your collection starts here.</h2><p>Browse digital products or restore a purchase pass.</p></div>'}</section><aside class="panel"><div class="panel-body"><div class="eyebrow">PURCHASE PASSES</div><h2>Keep access.</h2><p class="muted">Each pass belongs to one purchase. Export it to restore access in another browser.</p><p class="note">Keep your pass private. It contains the key used to authorize refund requests.</p></div></aside></div>`;
 bind('sync',buyer);bind('browseProducts',()=>browse());bind('import',()=>document.querySelector('#file').click());document.querySelector('#file').addEventListener('change',restore);
 for(const p of list){bind('review-'+p.receipt.id,()=>reviewForm(p));bind('download-'+p.receipt.id,()=>downloadProduct(p));bind('export-'+p.receipt.id,()=>exportPass(p));bind('refund-'+p.receipt.id,()=>refundForm(p));}
}
function purchaseNotice(n,refund){
 const original='Edition 1.0 was missing the observation checklist. Download the corrected edition, or request a refund if it no longer meets your needs.';
 return ['confirmed','simulated'].includes(refund?.status)&&n.body===original
  ? 'Edition 1.1 includes the missing observation checklist. The corrected edition remains available to download.'
  : n.body;
}
function purchaseHTML(p){const item=itemFor(p.receipt.product);const state=statuses.get(p.receipt.id);const refund=state?.refund;const n=notices.find(n=>n.product===p.receipt.product&&n.version===p.receipt.version);return `<article class="purchase" data-purchase="${esc(p.receipt.id)}"><div class="purchase-top"><div class="product-identity"><div class="mini-cover" aria-hidden="true">${esc(item.mark||"V")}</div><div><h3>${esc(item.name)}</h3><span class="muted small">${esc(item.seller)} · Edition ${esc(p.receipt.version)}</span></div></div><span class="badge">Pass saved</span></div><p class="meta">${new Date(p.receipt.issuedAt).toLocaleDateString()} · ${esc(p.receipt.amount)} ${esc(p.receipt.asset)} · ${p.receipt.paymentMode==='testnet'?'Confirmed on testnet':'Simulated purchase'}</p>${refund?refundTracker(refund,state):''}${n?`<div class="notice"><h3>${esc(n.title)}</h3><p>${esc(state?.downloadAllowed===false?'Your refund is complete. Future downloads have ended for this purchase.':purchaseNotice(n,refund))}</p></div>`:'<p class="muted small">No release notices. You’re up to date.</p>'}<div class="actions"><button class="btn quiet" id="review-${p.receipt.id}">Write or edit review</button><button class="btn quiet" id="export-${p.receipt.id}">Export purchase pass</button>${true?`<button class="btn primary" id="download-${p.receipt.id}" ${state?.downloadAllowed===false?'disabled':''}>${state?.downloadAllowed===false?'Download access ended':'Download files'}</button>${state?.unavailable?'<span class="status-unavailable">Status unavailable · refresh to retry</span>':refund&&refund.status!=='withdrawn'?'':(true?`<button class="btn quiet" id="refund-${p.receipt.id}">Request refund</button>`:'')}`:''}</div></article>`;}
async function simulationCheckout(productId="fieldnotes"){const selected=itemFor(productId);app.innerHTML=`<div class="form"><div class="eyebrow">${esc(selected.seller)} / Checkout</div><h1>${esc(selected.name)}</h1><p class="muted">Receive your download and a reusable purchase pass. No account required.</p><div class="price"><span>Total</span><strong>${esc(selected.price)} ZEC</strong></div><button class="btn primary full" id="pay">Simulate payment</button><p class="field-note">No ZEC is transferred in this simulation. Completing a refund ends future downloads; downloaded files cannot be recalled.</p><button class="btn quiet full" id="back">Back to purchases</button></div>`;bind('back',buyer);bind('pay',async()=>{
 const keys=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},true,['sign','verify']);const publicKey=await crypto.subtle.exportKey('jwk',keys.publicKey),privateKey=await crypto.subtle.exportKey('jwk',keys.privateKey);
 const order=await api('/api/purchases',{key:publicKey,productId});
 // Retain the purchase key before payment so an interrupted request can be recovered.
 localStorage.setItem('veylo.pending',JSON.stringify({id:order.id,privateKey}));
 const receipt=await api('/api/simulate-payment',{id:order.id});keep({receipt,privateKey});localStorage.removeItem('veylo.pending');await buyer();toast('Purchase saved. Export your pass to back it up.');});}

function refundTracker(r,state={}){
 const confirmed=r.status==='confirmed',sent=['broadcast','confirmed'].includes(r.status);
 const labels=['Request received','Seller review','Payment sent','Confirmed'];
 const completed=[true,sent,sent,confirmed];
 const active=r.status==='requested'?1:sent&&!confirmed?3:!confirmed?2:-1;
 const date=t=>t?new Date(t).toLocaleString():'';
 return `<section class="refund-progress refund-tracker" aria-label="Refund progress"><div class="refund-tracker-head"><h3>${esc(refundLabel(r.status))}</h3><span>${esc(r.amount)} ${esc(r.asset)} refund</span></div><p class="refund-summary" role="status">${esc(state.unavailable?'Latest status unavailable. Showing the last known result; retrying automatically.':refundProgress(r))}</p>${['simulated','withdrawn','declined'].includes(r.status)?'':`<ol class="refund-stages">${labels.map((label,i)=>`<li class="${completed[i]?'complete':i===active?'current':''}" ${i===active?'aria-current="step"':''}><span aria-hidden="true">${completed[i]?'✓':i+1}</span>${label}</li>`).join('')}</ol>`}<dl class="refund-facts"><div><dt>Requested</dt><dd>${esc(date(r.createdAt))}</dd></div>${r.withdrawnAt?`<div><dt>Withdrawn</dt><dd>${esc(date(r.withdrawnAt))}</dd></div>`:''}${r.decidedAt?`<div><dt>Decision date</dt><dd>${esc(date(r.decidedAt))}</dd></div>`:''}${r.decisionReason?`<div><dt>Seller’s explanation</dt><dd>${esc(r.decisionReason)}</dd></div>`:''}${r.completedAt?`<div><dt>Completed</dt><dd>${esc(date(r.completedAt))}</dd></div>`:''}${r.reason?`<div><dt>Your reason</dt><dd>${esc(r.reason)}</dd></div>`:''}</dl><details><summary>Payment details</summary>${r.destination?`<p class="note">Refund address</p><div class="address">${esc(r.destination)}</div>`:''}${r.txid?`<p class="note">Transaction ID</p><div class="address">${esc(r.txid)}</div>`:'<p class="note">No refund transaction has been recorded yet.</p>'}</details>${r.status==='requested'&&r.id?`<button class="btn quiet" data-withdraw-refund="${esc(r.id)}">Withdraw request</button>`:''}<p class="note refund-checked">${state.checkedAt?'Last checked '+esc(date(state.checkedAt))+'. ':''}${confirmed||['simulated','declined'].includes(r.status)?'':'Updates automatically while Purchases is open and this tab is visible.'}</p></section>`;
}
function refundProgress(r){
 if(r.status==='broadcast')return `Payment submitted · ${Number(r.confirmations)||0}/10 confirmations. Checking automatically.`;
 if(['sending','unknown'].includes(r.status))return 'Checking the wallet automatically. No further payment will be sent.';
 return refundDescription(r.status);
}
function refundLabel(s){return ({declined:'Refund declined',withdrawn:'Request withdrawn',requested:'Awaiting seller review',sending:'Checking payment outcome',unknown:'Payment outcome needs checking',broadcast:'Refund confirming',confirmed:'Refund confirmed',needs_review:'Seller review required',simulated:'Refund simulation complete'})[s]||'Status unavailable';}
function refundDescription(s){return ({declined:'The seller declined this request. No refund was sent. Your download access remains available.',withdrawn:'No refund was sent for this request. You can submit a new request with the correct receiving address.',requested:'Your signed request is awaiting the seller’s approval.',sending:'A payment attempt has been recorded. Do not submit another.',unknown:'The seller must reconcile the wallet before any further action.',broadcast:'The refund was submitted and is awaiting confirmation.',confirmed:'The seller wallet reports the refund mined with at least 10 confirmations.',needs_review:'Conflicting payment evidence needs manual review.',simulated:'No funds were transferred for this simulated purchase.'})[s]||'';}
async function checkout(productId="fieldnotes"){
 view="checkout";nav();
 if(catalog.paymentMode!=='testnet')return simulationCheckout(productId);
 let pending=JSON.parse(localStorage.getItem('veylo.pending')||'null');
 if(pending&&!pending.invoice){
 app.innerHTML='<div class="form"><h1>Saved checkout needs attention</h1><p class="muted">Payment instructions are missing from this saved checkout. You can close it and preserve its purchase key in History. Closing checkout does not reverse a payment.</p><button class="btn primary full" id="archiveIncomplete">Cancel checkout</button><button class="btn quiet full" id="incompleteBack">Back to browse</button></div>';
 bind('archiveIncomplete',async()=>{archiveCheckout(localStorage);await browse();toast('Checkout saved in History.');});
 bind('incompleteBack',()=>browse());
 return;
}
 if(!pending){
  app.innerHTML='<div class="form"><h1>Preparing checkout</h1><p>Syncing the seller wallet and creating your payment request…</p></div>';
  const keys=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},true,['sign','verify']);
  const key=await crypto.subtle.exportKey('jwk',keys.publicKey),privateKey=await crypto.subtle.exportKey('jwk',keys.privateKey);
  let invoice;try{invoice=await api('/api/purchases',{key,productId});}catch(e){await buyer();throw e;}
  pending={id:invoice.id,privateKey,invoice,createdAt:new Date().toISOString()};localStorage.setItem('veylo.pending',JSON.stringify(pending));
 }
 const i=pending.invoice;
 const selected=i.product;
 const uri=`zcash:${i.address}?amount=${i.product.price}&memo=${b64(bytes(i.memo))}`;
 const command=`"$HOME/Developer/veylo-zcash-devtool-nu7-candidate/target/release/zcash-devtool" wallet -w "$HOME/veylo-test-wallets/buyer" sync --server zecrocks &&\n"$HOME/Developer/veylo-zcash-devtool-nu7-candidate/target/release/zcash-devtool" wallet -w "$HOME/veylo-test-wallets/buyer" send --identity "$HOME/veylo-test-wallets/buyer.age" --address "${i.address}" --value ${i.value} --memo "${i.memo}" --server zecrocks`;
 app.innerHTML=`<div class="form live-checkout"><div class="eyebrow">${esc(selected.seller)} / Checkout</div><h1>Pay privately.</h1><p class="muted">Your purchase pass is issued after the seller wallet verifies your payment.</p><div class="price"><span>${esc(selected.name)} · Edition ${esc(selected.version)}</span><strong>${esc(i.product.price)} TAZ</strong></div><p class="field-note">A confirmed refund ends future downloads. Files already downloaded remain on your device.</p><span class="badge">Zcash testnet</span><label>Receiving address</label><div class="address">${esc(i.address)}</div><label>Payment reference</label><div class="address">${esc(i.memo)}</div><p class="field-note">Include the exact reference as the payment memo. Pay once; network fees are additional.</p><div class="actions"><a class="btn" href="${esc(uri)}">Open compatible wallet</a><button class="btn quiet" id="copyLink">Copy payment link</button></div><details class="wallet-command"><summary>Use your local test wallet</summary><p>Run once in Terminal. If the result is uncertain, check the wallet before repeating.</p><pre>${esc(command)}</pre><button class="btn" id="copyCommand">Copy command</button></details><p id="paymentStatus" role="status">Checking payment automatically…</p><p class="field-note" id="paymentCheckTime">Keep this checkout open. Checks run automatically while this tab is visible.</p><button class="btn primary full" id="checkPayment">Check now</button><button class="btn quiet full" id="cancelCheckout">Cancel checkout</button><button class="btn quiet full" id="back">Back to purchases</button></div>`;
 bind('cancelCheckout',cancelCheckout);bind('back',buyer);bind('copyCommand',async()=>{await navigator.clipboard.writeText(command);toast('Payment command copied. Run it once.');});
 bind('copyLink',async()=>{await navigator.clipboard.writeText(uri);toast('Payment link copied.');});
 const status=document.querySelector('#paymentStatus'),checked=document.querySelector('#paymentCheckTime'),button=document.querySelector('#checkPayment');
 checkoutWatch=watchPayment({
  check:()=>api('/api/check-payment',{id:i.id,token:i.token}),
  active:()=>!document.hidden&&view==='checkout'&&status.isConnected,
  onBusy:busy=>{button.disabled=busy;button.textContent=busy?'Checking…':'Check now';},
  onResult:async result=>{
   if(result.status==='confirmed'){
    if(!result.receipt||result.receipt.id!==i.id)throw Error('Payment receipt does not match this checkout.');
    keep({receipt:result.receipt,privateKey:pending.privateKey});
    const current=JSON.parse(localStorage.getItem('veylo.pending')||'null');
    if(current?.id===i.id)localStorage.removeItem('veylo.pending');
    await buyer();toast('Payment confirmed. Your purchase is ready. Export your pass to keep access.');
   }else{
    status.textContent=result.status==='confirming'?`Payment detected · ${result.confirmations}/${result.confirmationsRequired} confirmations`:'Waiting for payment · checking automatically';
    checked.textContent=`Last checked ${new Date().toLocaleTimeString()}. Next check in about 15 seconds.`;
   }
  },
  onError:()=>{status.textContent='Payment check unavailable. Your checkout is saved. If you already sent payment, do not send it again.';checked.textContent='Retrying automatically in about 15 seconds. You can also select Check now.';}
 });
 button.addEventListener('click',()=>checkoutWatch?.refresh());
}
async function exportPass(p){if(!confirm('This file includes the key that controls this purchase. Keep it private. Anyone with the file can request its refund. Continue?'))return;download(`veylo-pass-${p.receipt.id.slice(0,8)}.json`,JSON.stringify({schema:'veylo.pass.v1',merchantKey:catalog.merchantKey,...p},null,2));}
async function restore(e){try{const file=e.target.files[0];if(!file)return;if(file.size>20000)throw Error('This file is too large to be a purchase pass.');const p=JSON.parse(await file.text());if(p.schema!=='veylo.pass.v1'||!p.receipt||!p.privateKey)throw Error('Invalid purchase pass.');
 const issuer=await crypto.subtle.importKey('jwk',catalog.merchantKey,'Ed25519',false,['verify']);if(!await crypto.subtle.verify('Ed25519',issuer,un64(p.receipt.signature),bytes(receiptPayload(p.receipt))))throw Error('The purchase receipt is not signed by this seller.');
 const key=await crypto.subtle.importKey('jwk',p.privateKey,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);const challenge=crypto.getRandomValues(new Uint8Array(32));const sig=await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,challenge);const pub=await crypto.subtle.importKey('jwk',p.receipt.purchaseKey,{name:'ECDSA',namedCurve:'P-256'},false,['verify']);if(!await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},pub,sig,challenge))throw Error('Purchase key does not match the receipt.');keep({receipt:p.receipt,privateKey:p.privateKey});await buyer();toast('Purchase restored.');}catch(err){toast(err.message);}}
app.addEventListener('click',async event=>{
 const button=event.target.closest('[data-withdraw-refund]');if(!button)return;
 const row=button.closest('[data-purchase]'),p=passes().find(p=>p.receipt.id===row?.dataset.purchase);if(!p)return;
 if(!confirm('Withdraw this refund request? You can then submit a new request with the correct address.'))return;
 button.disabled=true;
 try{
  const c=await api('/api/challenges',{id:p.receipt.id});
  const request={purchaseId:p.receipt.id,nonce:c.nonce,requestId:button.dataset.withdrawRefund};
  const key=await crypto.subtle.importKey('jwk',p.privateKey,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);
  const signature=b64(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,bytes(JSON.stringify(['veylo.refund.withdraw.v1',request.purchaseId,request.nonce,request.requestId]))));
  await api('/api/refunds/withdraw',{request,signature});
  if(view==='buyer')await buyer();toast('Request withdrawn. You can now submit a corrected request.');
 }catch(error){toast(error.message);button.disabled=false;}
});
function refundForm(p){const item=itemFor(p.receipt.product);app.innerHTML=`<div class="form"><div class="eyebrow">${esc(item.name)} / Refund</div><h1>Choose where it returns.</h1><p class="muted">Tell the seller what went wrong and where to send an approved refund. Approval is not automatic.</p><label for="refundReason">Reason for refund</label><textarea id="refundReason" maxlength="1000" placeholder="Explain why the product did not meet your expectations."></textarea><p class="field-note">Your reason is shared privately with the seller, not posted as a public review.</p><label for="destination">Receiving address</label><input id="destination" autocomplete="off" placeholder="Paste your shielded receiving address"><p class="field-note">${p.receipt.paymentMode==='testnet'?'Use a shielded testnet address. Your signature binds the refund to this exact address.':'Simulation only. No funds will be sent.'}</p><button class="btn primary full" id="request">Sign refund request</button><button class="btn quiet full" id="back">Back</button></div>`;bind('back',buyer);bind('request',async()=>{const destination=document.querySelector('#destination').value.trim();const reason=document.querySelector('#refundReason').value.trim();if(!reason)throw Error('Please explain why you are requesting a refund.');const c=await api('/api/challenges',{id:p.receipt.id});const request={purchaseId:p.receipt.id,nonce:c.nonce,destination,reason};const key=await crypto.subtle.importKey('jwk',p.privateKey,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);const signature=b64(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,bytes(JSON.stringify(['veylo.refund.v2',request.purchaseId,request.nonce,request.destination,request.reason]))));await api('/api/refunds',{request,signature});localStorage.setItem('veylo.request.'+p.receipt.id,'requested');await buyer();toast('Request signed and sent to the seller.');});}
async function seller(desk=false){view='seller';nav();let account;try{account=await api('/api/store-account');}catch{}if(account&&!desk)return storeAccountPage(account);let data;try{data=await api('/api/seller');}catch{app.innerHTML=`<div class="form"><div class="eyebrow">Seller console</div><h1>Your seller workspace.</h1><div class="actions"><button class="btn primary" id="newStore">Create a store</button><button class="btn" id="storeSignIn">Seller sign in</button></div><h2>Existing store operator</h2><p class="muted">Use the seller access code printed in your terminal.</p><label for="code">Access code</label><input id="code" type="password" autocomplete="current-password"><div class="actions"><button class="btn primary full" id="login">Open console</button></div><p class="note">Your access code is shown in the running server’s terminal.</p></div>`;bind('newStore',()=>storeAccountAuth(true));bind('storeSignIn',()=>storeAccountAuth(false));bind('login',async()=>{await api('/api/seller/login',{code:document.querySelector('#code').value});await seller();});return;}
 const owned=(await api('/api/seller/products')).products;
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">MERCHANT DESK</div><h1>Seller console</h1><p class="sub">${data.purchases} ${data.purchases===1?'purchase':'purchases'} · ${data.requests.filter(r=>r.status==='requested').length} awaiting review</p></div><div class="actions"><button class="btn primary" id="manageProducts">Manage store</button><button class="btn" id="refresh">Refresh</button><button class="btn quiet" id="logout">Sign out</button></div></div><div class="seller-grid"><section class="panel"><div class="panel-head"><h2>Refund requests</h2><span class="count">${data.requests.length} total</span></div>${data.requests.length?data.requests.map(r=>`<article class="request" data-request="${esc(r.id)}"><div class="purchase-top"><h3>${esc(itemFor(r.productId).name)} · ${esc(r.amount)} ${esc(r.asset||'ZEC')}</h3><span class="badge">${refundLabel(r.status)}</span></div><p class="meta">Purchase ${esc(r.purchaseId.slice(0,8))} · ${new Date(r.createdAt).toLocaleString()}</p><p class="small"><strong>Buyer’s reason:</strong> ${esc(r.reason||"No reason supplied with this earlier request.")}</p><div class="address">${esc(r.destination)}</div>${r.status==='requested'?`<button class="btn primary" id="approve-${r.id}">${r.paymentMode==='testnet'?'Approve & send refund':'Approve & simulate refund'}</button><button class="btn quiet" id="decline-${r.id}">Decline request</button>`:`<p class="small muted">${refundProgress(r)}</p>${r.decisionReason?`<p class="small"><strong>Your explanation:</strong> ${esc(r.decisionReason)}</p>`:''}${r.txid?`<div class="address">Transaction: ${esc(r.txid)}</div>`:''}`}</article>`).join(''):'<div class="empty"><div class="inbox-art" aria-hidden="true"><span>✓</span></div><h2>You’re all caught up.</h2><p>New refund requests appear here, ready for your review.</p></div>'}</section><aside class="panel"><div class="panel-body"><div class="eyebrow">Release notice</div><h2>Publish an update.</h2><p class="muted small">Choose the product receiving this release notice. Buyers can request refunds independently of release notices.</p><label for="noticeProduct">Product</label><select id="noticeProduct">${owned.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.version)}</option>`).join('')}</select><label for="title">Title</label><input id="title" maxlength="120" placeholder="e.g. A corrected edition is available"><label for="message">Message</label><textarea id="message" maxlength="2000" placeholder="Explain what changed and what customers can do next."></textarea><button class="btn primary full" id="publish">Publish notice</button><p class="note">Buyers see updates for the editions they own.</p></div></aside></div>`;
 bind('manageProducts',manageStore);
 bind('refresh',async()=>{if(catalog.paymentMode==='testnet')await api('/api/seller/check-refunds',{});await seller();});bind('logout',async()=>{await api('/api/seller/logout',{});await seller();});bind('publish',async()=>{await api('/api/seller/notices',{productId:document.querySelector('#noticeProduct').value,title:document.querySelector('#title').value,body:document.querySelector('#message').value});toast('Release notice published. Refresh the buyer view to see it.');await seller();});for(const r of data.requests)bind('decline-'+r.id,()=>declineForm(r));for(const r of data.requests)bind('approve-'+r.id,async()=>{if(r.paymentMode==='testnet'){if(!confirm(`Send ${r.amount} TAZ plus the network fee to ${r.destination}?`))return;try{await api('/api/seller/send-refund',{id:r.id});}finally{await seller();}toast('Refund submitted. Confirmations update automatically.');}else{await api('/api/seller/simulate-refund',{id:r.id});await seller();toast('Refund simulated. No funds were transferred.');}});
}
bind('historyNav',historyPage);bind('helpNav',howItWorks);bind('browseNav',()=>browse());bind('buyerNav',buyer);bind('sellerNav',seller);
try{catalog=await api('/api/catalog');document.querySelector('.network').textContent=catalog.paymentMode==='testnet'?'Zcash testnet':'Payment simulation';document.querySelector('footer span:last-child').textContent=catalog.paymentMode==='testnet'?'Shielded payments · Testnet':'Payments are simulated.';const pending=JSON.parse(localStorage.getItem('veylo.pending')||'null');await browse();}catch(err){app.textContent='Unable to load Veylo. '+err.message;}


let automaticStatusBusy=false;
function declineForm(r){
 view='seller-decision';nav();
 app.innerHTML=`<div class="form"><div class="eyebrow">Refund decision</div><h1>Decline request</h1><p class="muted">${esc(itemFor(r.productId).name)} · ${esc(r.amount)} ${esc(r.asset)}</p><p><strong>Buyer’s reason:</strong> ${esc(r.reason||'No reason supplied.')}</p><label for="decisionReason">Explain your decision</label><textarea id="decisionReason" maxlength="1000" placeholder="Explain why you are declining this request."></textarea><p class="field-note">The buyer will see this explanation privately. No refund will be sent, and their download access will remain available. This closes the request.</p><button class="btn primary full" id="confirmDecline">Confirm decline</button><button class="btn quiet full" id="cancelDecline">Back to seller console</button></div>`;
 bind('cancelDecline',seller);bind('confirmDecline',async()=>{const reason=document.querySelector('#decisionReason').value.trim();if(!reason)throw Error('Please explain your decision.');await api('/api/seller/decline-refund',{id:r.id,reason});await seller();toast('Decision saved. The buyer can see your explanation.');});
}
async function automaticStatus(){
 if(automaticStatusBusy||document.hidden||catalog?.paymentMode!=='testnet')return;
 automaticStatusBusy=true;
 try{
  if(view==='buyer'&&app.querySelector('.collection')){
   for(const p of passes()){
    if(p.receipt.paymentMode!=='testnet')continue;
    const before=statuses.get(p.receipt.id)?.refund;
    if(before&&['confirmed','simulated'].includes(before.status))continue;
    await loadStatus(p);
    if(view!=='buyer')break;
    const row=app.querySelector(`[data-purchase="${CSS.escape(p.receipt.id)}"]`);
    const r=statuses.get(p.receipt.id)?.refund;
    if(!row)continue;
    const progress=row.querySelector('.refund-progress');
    if(statuses.get(p.receipt.id)?.unavailable){if(progress&&r)progress.outerHTML=refundTracker(r,statuses.get(p.receipt.id));continue;}
    const dl=document.getElementById('download-'+p.receipt.id);if(dl&&statuses.get(p.receipt.id)?.downloadAllowed===false){dl.disabled=true;dl.textContent='Download access ended';}
    if(r){if(progress)progress.outerHTML=refundTracker(r,statuses.get(p.receipt.id));else row.querySelector('.actions').insertAdjacentHTML('beforebegin',refundTracker(r,statuses.get(p.receipt.id)));if(r.status!=='withdrawn')document.getElementById('refund-'+p.receipt.id)?.remove();const n=notices.find(n=>n.product===p.receipt.product&&n.version===p.receipt.version);const notice=row.querySelector('.notice p');if(n&&notice)notice.textContent=statuses.get(p.receipt.id)?.downloadAllowed===false?'Your refund is complete. Future downloads have ended for this purchase.':purchaseNotice(n,r);}
   }
  }else if(view==='seller'&&app.querySelector('.seller-grid')){
   const data=await api('/api/seller');
   if(view!=='seller')return;
   for(const r of data.requests){
    const row=app.querySelector(`[data-request="${CSS.escape(r.id)}"]`);
    if(!row)continue;if(r.status!=='requested')row.querySelectorAll('button').forEach(b=>b.remove());
    row.querySelector('.badge').textContent=refundLabel(r.status);
    const detail=row.querySelector('p.small.muted');if(detail)detail.textContent=refundProgress(r);
   }
  }
 }catch{
  // Keep the last known status; a failed read never becomes a confirmed payment.
 }finally{automaticStatusBusy=false;}
}
setInterval(automaticStatus,10000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)automaticStatus();});

function productPreview(p){
 const title=`<span>${esc(p.kind)}</span><h2>${esc(p.name)}</h2>`;
 if(p.id==='pixelpress')return title+'<div class="preview-window"><div class="window-dots">● ● ●</div><div class="preview-landscape"><i></i><b>1200 × 800</b></div><div class="preview-toolbar">Resize <span>Export ↗</span></div></div>';
 if(p.id==='contour')return title+'<div class="preview-icons" aria-hidden="true">'+['↗','✓','+','✕','↓','↑','▱','✉','▷','Ⅱ','◇','▦'].map(v=>'<i>'+v+'</i>').join('')+'</div><small>12 SVG ICONS · 24 PX GRID</small>';
 if(p.id==='chime')return title+'<div class="preview-wave" aria-hidden="true">'+Array.from({length:28},(_,i)=>'<i class="wave-'+(i%7)+'"></i>').join('')+'</div><small>4 SOUNDS · WAV · 44.1 KHZ</small>';
 if(p.id!=='fieldnotes')return title+`<div class="preview-download"><span>${esc(p.mark||'V')}</span><small>${esc(p.format||'DIGITAL DOWNLOAD')}</small></div>`;
 return title+'<div class="preview-journal">FIELD<br>NOTES<span>Observe. Record. Return.</span></div>';
}
async function downloadProduct(p){
 const c=await api('/api/challenges',{id:p.receipt.id});const request={purchaseId:p.receipt.id,nonce:c.nonce};
 const key=await crypto.subtle.importKey('jwk',p.privateKey,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);
 const signature=b64(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,bytes(JSON.stringify(['veylo.download.v1',request.purchaseId,request.nonce]))));
 const res=await fetch('/api/download',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request,signature})});
 if(!res.ok){const e=await res.json();throw Error(e.error||'Download unavailable.');}
 const blob=await res.blob();if(p.receipt.delivery){const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==p.receipt.delivery.sha256||blob.size!==p.receipt.delivery.bytes)throw Error('The downloaded file does not match your signed receipt.');}const name=res.headers.get('Content-Disposition')?.match(/filename="([A-Za-z0-9._ -]+)"/)?.[1]||'veylo-download';download(name,blob,blob.type);
}

function ratingSummary(id){
 const rows=publicReviews.filter(r=>r.product===id&&r.paymentMode===catalog.paymentMode);
 if(!rows.length)return '<p class="rating-summary">'+(publicReviews.some(r=>r.product===id)?'Earlier simulation feedback below':'No reviews yet')+'</p>';
 return `<p class="rating-summary">★ ${(rows.reduce((n,r)=>n+r.rating,0)/rows.length).toFixed(1)} <span>· ${rows.length} ${rows.length===1?'review':'reviews'}</span></p>`;
}
function reviewsHTML(){return `<section class="panel public-reviews"><div class="panel-head"><div><h2>Buyer reviews</h2><p class="muted small">Feedback from purchase-pass holders. Earlier simulation reviews are labelled and excluded from testnet ratings.</p></div></div>${publicReviews.length?[...publicReviews.filter(r=>r.paymentMode===catalog.paymentMode),...publicReviews.filter(r=>r.paymentMode!==catalog.paymentMode)].map(r=>`<article class="public-review"><div class="purchase-top"><h3>${esc(itemFor(r.product).name)}</h3><span class="review-stars" aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><p class="review-text">${esc(r.text)}</p><p class="note">${esc(itemFor(r.product).seller)} · ${r.paymentMode==='testnet'?'Verified testnet purchase':'Simulated purchase'} · Updated ${new Date(r.updatedAt).toLocaleDateString()}</p></article>`).join(''):'<div class="empty"><h3>Be the first to share your experience.</h3><p>Buyers can post a review from Your purchases.</p></div>'}</section>`;}
async function reviewForm(p){await loadStatus(p);const saved=statuses.get(p.receipt.id)?.review;app.innerHTML=`<div class="form"><div class="eyebrow">${esc(itemFor(p.receipt.product).name)} / Buyer review</div><h1>Share your experience.</h1><p class="muted">Was the product accurately described? Did the seller handle updates and refunds fairly?</p><label for="reviewRating">Rating</label><select id="reviewRating"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Mixed</option><option value="2">2 — Poor</option><option value="1">1 — Very poor</option></select><label for="reviewText">Your review</label><textarea id="reviewText" maxlength="1000" placeholder="Describe what happened and what other buyers should know."></textarea><p class="field-note">Your rating and text will be public. Do not include personal details, wallet addresses, or your purchase pass. Posting again replaces your previous review for this purchase.</p><button class="btn primary full" id="postReview">Publish review</button><button class="btn quiet full" id="back">Back</button></div>`;if(saved){document.querySelector('#reviewRating').value=String(saved.rating);document.querySelector('#reviewText').value=saved.text;}bind('back',buyer);bind('postReview',async()=>{
 const rating=Number(document.querySelector('#reviewRating').value),text=document.querySelector('#reviewText').value.trim();if(!text)throw Error('Write your review before publishing.');
 const c=await api('/api/challenges',{id:p.receipt.id});const request={purchaseId:p.receipt.id,nonce:c.nonce,rating,text};
 const key=await crypto.subtle.importKey('jwk',p.privateKey,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);
 const signature=b64(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,bytes(JSON.stringify(['veylo.review.v1',request.purchaseId,request.nonce,rating,text]))));
 await api('/api/reviews',{request,signature});await browse();document.querySelector('.public-reviews')?.scrollIntoView({block:'start'});toast(p.receipt.paymentMode==='testnet'?'Your review is public.':'Your review is public under simulated purchases.');});}

async function cancelCheckout(){
 if(!confirm('Cancel this checkout? This does not reverse a payment already sent. A recovery copy stays in this browser in History.'))return;
 archiveCheckout(localStorage);await browse();toast('Checkout cancelled. You can choose another product.');
}

async function historyPage(){
 view='history';nav();const list=passes();await Promise.all(list.map(loadStatus));if(view!=='history')return;
 const completed=new Set(list.map(p=>p.receipt.id));const pending=JSON.parse(localStorage.getItem('veylo.pending')||'null');
 const archived=JSON.parse(localStorage.getItem('veylo.cancelled')||'[]').filter(p=>!completed.has(p.id)&&p.id!==pending?.id);
 const rows=list.map(p=>{const status=statuses.get(p.receipt.id),refund=status?.refund;return {id:p.receipt.id,name:itemFor(p.receipt.product).name,date:p.receipt.issuedAt,amount:p.receipt.amount,asset:p.receipt.asset,label:refund?refundLabel(refund.status):p.receipt.paymentMode==='testnet'?'Successful':'Simulated purchase',detail:status?.unavailable?'Latest refund status unavailable. Refresh to retry.':refund?refundProgress(refund):'Purchase pass issued. Downloads and reviews are in Purchases.',action:'purchase'};});
 if(pending&&!completed.has(pending.id))rows.push({id:pending.id,name:pending.invoice?.product?.name||'Pending checkout',date:pending.createdAt||null,amount:pending.invoice?.product?.price,asset:pending.invoice?.product?.asset,label:'Pending',detail:'Payment status has not been confirmed. Resume to check it.',action:'resume'});
 for(const p of archived)rows.push({id:p.id,name:p.invoice?.product?.name||'Saved checkout',date:p.cancelledAt,amount:p.invoice?.product?.price,asset:p.invoice?.product?.asset,label:'Cancelled',detail:'Checkout closed in this browser. Any payment already sent is not reversed.',action:'recover'});
 rows.sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0));
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">YOUR ACTIVITY</div><h1>History</h1><p class="sub">Purchases, refunds, and checkouts saved in this browser.</p></div><button class="btn" id="refreshHistory">Refresh status</button></div><section class="panel">${rows.length?rows.map((r,i)=>`<article class="history-row"><div><h3>${esc(r.name)}</h3><p class="meta">${r.date?new Date(r.date).toLocaleString():'Awaiting completion'}${r.amount?' · '+esc(r.amount)+' '+esc(r.asset):''}</p><p class="muted small">${esc(r.detail)}</p></div><div class="history-action"><span class="badge">${esc(r.label)}</span><button class="btn quiet" id="history-${i}">${r.action==='purchase'?'View purchases':r.action==='resume'?'Resume checkout':'Recover checkout'}</button></div></article>`).join(''):'<div class="empty"><h2>No activity yet.</h2><p>Your purchase and checkout history will appear here.</p><button class="btn primary" id="historyBrowse">Browse products</button></div>'}</section>`;
 bind('refreshHistory',historyPage);bind('historyBrowse',()=>browse());rows.forEach((r,i)=>bind('history-'+i,async()=>{if(r.action==='purchase')return buyer();if(r.action==='recover')recoverCheckout(localStorage,r.id);await checkout();}));
}
function howItWorks(audience='buyer'){
 view='help';nav();
 const buyerSteps=[
 ['Choose your product','Open a product to check its description, included file, edition, price and buyer reviews. Purchase totals count completed orders, not unique people.'],
 ['Complete checkout','Pay the exact amount to the checkout address with the supplied payment memo. Use a compatible Zcash wallet or the local-wallet command. Pay once and allow for the separate network fee.'],
 ['Receive your download','Keep checkout open and visible for automatic checks. The seller wallet must verify the matching payment with at least 10 confirmations. Your purchase then appears in Purchases with its download and purchase pass.'],
 ['Back up your purchase pass','Select Export purchase pass in Purchases. Keep the file private: it contains the key controlling this purchase. In another browser, select Restore purchase and import it. Restoring does not reverse a completed refund or restore revoked downloads.'],
 ['Request a refund','Open Purchases, choose Request refund, explain the problem and enter a shielded receiving address from your own wallet. Sign the request. No seller announcement is needed. Your explanation is private to the seller.'],
 ['Follow the decision','Your tracker shows seller review, payment submission and confirmation. The seller may approve or decline with an explanation. While awaiting review, you can withdraw and submit a corrected request. Withdrawal stops being available once payment processing starts.'],
 ['Review your purchase','Write one public rating and review per purchase, and edit it later if needed. You can still review after a refund. Keep wallet addresses, purchase passes and personal information out of your review.']
 ];
 const sellerSteps=[
 ['Open your seller console','Sign in with the seller access code for this store. This installation uses one configured seller wallet; new sellers can register and prepare private drafts. Their sales require an online payment connector.'],
 ['Publish a product','In Manage store, add a name, description, category, version, price and downloadable file. Supported files are ZIP, PDF, TXT, PNG, JPG and WAV, up to 8 MiB. Use ZIP for a collection of files.'],
 ['Preserve each edition','The uploaded file is fixed for that edition. New purchase receipts record its fingerprint. Publish a separate product for a new edition. Archive a listing to stop new purchases while preserving existing orders and eligible downloads.'],
 ['Keep buyers informed','Publish a release notice for a product and edition. Owners see the update in Purchases. Notices are independent of refund requests: a buyer can request support without waiting for an announcement.'],
 ['Review refund requests','Read the buyer’s reason and receiving address. Approve & send refund returns the original purchase amount, with the network fee paid separately by the seller. Decline request requires a private explanation and leaves downloads available.'],
 ['Track payment completion','A submitted refund is not yet confirmed. Veylo checks the wallet and waits for 10 confirmations. If the payment outcome is uncertain, do not send another payment. Check the wallet and the recorded transaction first.']
 ];
 const faq=[
 ['Can I cancel checkout?','Yes. Open Resume checkout, then Cancel checkout. History keeps a recovery copy in this browser. Cancellation does not reverse a payment already sent; recover that checkout to check a late payment.'],
 ['Why is a payment still confirming?','Veylo needs a matching payment and 10 confirmations. Automatic checkout checks run while the page is visible. You can use Check now. Network or wallet errors may delay verification; do not pay again just because the page is waiting.'],
 ['What happens after a refund?','For new purchases, a completed refund ends future downloads. Files already downloaded cannot be recalled. Older purchases retain their original terms. Your public review may remain visible.'],
 ['Can I reopen a declined request?','Not in this version. A decline closes the request and the buyer sees the seller’s explanation. Appeals and reopening are not implemented.'],
 ['What if I lose my purchase pass?','If the purchase remains in your browser, export another copy. If both the browser data and exported pass are lost, Veylo has no email-based account recovery. A transaction ID alone does not replace the purchase key.'],
 ['Who can see my information?','No buyer email account is required. The store processes order information, received payments and refund details. Reviews are public. A purchase pass is private, but anyone with a copy can exercise that purchase’s permissions.']
 ];
 const steps=audience==='seller'?sellerSteps:buyerSteps;
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">VEYLO GUIDE</div><h1>How it works</h1><p class="sub">Buying, selling and support, step by step.</p></div><button class="btn primary" id="guideBrowse">Browse products</button></div><div class="guide-audiences" role="group" aria-label="Choose a guide"><button class="btn ${audience==='buyer'?'primary':'quiet'}" id="guideBuyer" aria-pressed="${audience==='buyer'}">For buyers</button><button class="btn ${audience==='seller'?'primary':'quiet'}" id="guideSeller" aria-pressed="${audience==='seller'}">For sellers</button></div><div class="guide-layout"><section class="panel">${steps.map(([title,text],i)=>`<article class="guide-step"><span class="guide-number">${i+1}</span><div><h2>${esc(title)}</h2><p>${esc(text)}</p></div></article>`).join('')}</section><aside><section class="panel panel-body"><h2>Payment network</h2><p>${catalog.paymentMode==='testnet'?'This installation uses Zcash testnet and TAZ. Payments and refunds are verified through the configured seller wallet.':'This installation uses payment simulation. No funds are transferred.'}</p></section><section class="panel panel-body"><h2>Keep your pass private</h2><p>Export it after purchase and store it safely. Never publish it with a review or send it as a screenshot.</p></section><section class="panel panel-body"><h2>Refunds require a decision</h2><p>Buyers can request a refund. Seller approval and a confirmed payment are required to complete it. Veylo does not guarantee that a seller will approve a request.</p></section></aside></div><section class="panel guide-faq"><div class="panel-head"><h2>Common questions</h2></div>${faq.map(([title,text])=>`<details><summary>${esc(title)}</summary><p>${esc(text)}</p></details>`).join('')}</section>`;
 bind('guideBrowse',()=>browse());bind('guideBuyer',()=>howItWorks('buyer'));bind('guideSeller',()=>howItWorks('seller'));
}

async function manageStore(){
 view='seller';nav();const data=await api('/api/seller/products');
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">SELLER / STORE</div><h1>Your store</h1><p class="sub">Manage your profile and the products available to buyers.</p></div><div class="actions"><button class="btn primary" id="newProduct">Add product</button><button class="btn" id="sellerBack">Refunds & updates</button></div></div><div class="store-layout"><section class="panel"><div class="panel-head"><h2>Products</h2><span class="count">${data.products.filter(p=>p.status==='published').length} published</span></div>${data.products.map(p=>`<article class="store-product"><div class="store-product-icon tone-${esc(p.tone)}">${esc(p.mark)}</div><div class="store-product-detail"><h3>${esc(p.name)}</h3><p class="meta">${esc(p.category)} · Version ${esc(p.version)} · ${esc(p.price)} ${catalog.paymentMode==='testnet'?'TAZ':'ZEC'}</p><p class="note">${esc(p.fileName||'No file available')}</p></div><div class="store-product-actions"><span class="badge">${p.status==='published'?'Published':'Archived'}</span><button class="btn quiet" data-product-details="${esc(p.id)}">Details</button><button class="btn quiet" data-product-status="${esc(p.id)}">${p.status==='published'?'Archive':'Publish'}</button></div></article>`).join('')}<div class="panel-body"><p class="note">Archiving removes a product from Browse. Existing purchases, pending payment requests and eligible downloads remain available.</p></div></section><aside class="panel panel-body store-profile"><div class="eyebrow">PUBLIC PROFILE</div><h2>Store details</h2><label for="storeName">Store name</label><input id="storeName" maxlength="60" value="${esc(data.profile.name)}"><label for="storeBio">About your store</label><textarea id="storeBio" maxlength="500">${esc(data.profile.bio)}</textarea><button class="btn primary full" id="saveStore">Save profile</button><p class="note">Payments are routed to the wallet connected to this store.</p></aside></div>`;
 bind('sellerBack',()=>seller(true));bind('newProduct',newProductForm);
 bind('saveStore',async()=>{await api('/api/seller/profile',{name:document.querySelector('#storeName').value,bio:document.querySelector('#storeBio').value});catalog=await api('/api/catalog');await manageStore();toast('Store profile saved.');});
 for(const button of app.querySelectorAll('[data-product-details]'))button.addEventListener('click',()=>productDetails(button.dataset.productDetails).catch(e=>toast(e.message)));
 for(const button of app.querySelectorAll('[data-product-status]'))button.addEventListener('click',async()=>{const p=data.products.find(p=>p.id===button.dataset.productStatus),status=p.status==='published'?'archived':'published';button.disabled=true;try{await api('/api/seller/products/status',{id:p.id,status});catalog=await api('/api/catalog');await manageStore();toast(status==='archived'?'Product archived. Existing purchases are preserved.':'Product published.');}catch(e){toast(e.message);button.disabled=false;}});
}
function newProductForm(){
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">SELLER / NEW PRODUCT</div><h1>Publish a product</h1><p class="sub">Add a clear description and the file your customers will receive.</p></div><button class="btn quiet" id="productBack">Back to store</button></div><section class="panel panel-body product-editor"><div class="editor-grid"><div><label for="productName">Product name</label><input id="productName" maxlength="80" placeholder="e.g. Studio Icons"><label for="productDescription">Description</label><textarea id="productDescription" maxlength="1000" placeholder="Explain what is included, who it is for, and how it can be used."></textarea><div class="editor-pair"><div><label for="productCategory">Category</label><select id="productCategory">${['Software','Design','Audio','Writing','Templates','Other'].map(c=>`<option>${c}</option>`).join('')}</select></div><div><label for="productVersion">Version</label><input id="productVersion" value="1.0" maxlength="24"></div></div></div><div><label for="productPrice">Price (${catalog.paymentMode==='testnet'?'TAZ':'ZEC'})</label><input id="productPrice" type="text" inputmode="decimal" placeholder="0.001"><p class="field-note">Up to eight decimal places. Network fees are paid separately.</p><label for="productFile">Downloadable file</label><input id="productFile" type="file" accept=".zip,.pdf,.txt,.png,.jpg,.jpeg,.wav"><p class="field-note">ZIP, PDF, TXT, PNG, JPG or WAV. Up to 8 MiB. Use a ZIP for multiple files.</p><div class="notice"><h3>A fixed edition</h3><p>The uploaded file is preserved for this edition. Each new purchase receipt records its SHA-256 fingerprint. Publish a separate product for a different edition.</p></div></div></div><div class="editor-footer"><p class="note">Buyers receive the file after payment verification. Buyers can request a refund; payment requires seller approval.</p><button class="btn primary" id="publishProduct">Publish product</button></div></section>`;
 bind('productBack',manageStore);bind('publishProduct',async()=>{
  const file=document.querySelector('#productFile').files[0];if(!file||!file.size||file.size>8*1024*1024)throw Error('Choose a non-empty file of up to 8 MiB.');
  const input={name:document.querySelector('#productName').value,description:document.querySelector('#productDescription').value,category:document.querySelector('#productCategory').value,version:document.querySelector('#productVersion').value,price:document.querySelector('#productPrice').value,fileName:file.name};
  const buffer=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<buffer.length;i+=8192)raw+=String.fromCharCode(...buffer.subarray(i,i+8192));input.fileBase64=btoa(raw);
  await api('/api/seller/products/publish',input);catalog=await api('/api/catalog');await manageStore();toast('Product published. It is now available in Browse.');
 });
}

async function productDetails(id){
 const data=await api('/api/product?id='+encodeURIComponent(id)),p=data.product,s=data.stats;
 view='product';nav();
 const fileSize=p.fileSize?`${(p.fileSize/1024).toFixed(p.fileSize<10240?1:0)} KB`:'Not listed';
 app.innerHTML=`<div class="heading"><button class="btn quiet" id="detailBack">← Browse</button><span class="badge">${esc(p.category)}</span></div><div class="product-detail-layout"><section><div class="catalog-cover detail-cover tone-${esc(p.tone)}">${productPreview(p)}</div><section class="panel panel-body detail-section"><h2>About this product</h2><p class="detail-description">${esc(p.description)}</p><dl class="product-facts"><div><dt>Version</dt><dd>${esc(p.version)}</dd></div><div><dt>Format</dt><dd>${esc(p.format||'Digital download')}</dd></div><div><dt>File size</dt><dd>${esc(fileSize)}</dd></div><div><dt>Delivery</dt><dd>Download after payment verification</dd></div></dl>${p.fileName?`<p class="note">Included file: ${esc(p.fileName)}</p>`:''}</section><section class="panel panel-body detail-section"><div class="panel-head detail-review-head"><h2>Buyer reviews</h2><span class="count">${s.reviewCount}</span></div>${s.reviews.length?s.reviews.map(r=>`<article class="public-review"><div class="purchase-top"><span class="review-stars" aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><span class="note">${new Date(r.updatedAt).toLocaleDateString()}</span></div><p class="review-text">${esc(r.text)}</p><p class="note">${s.paymentMode==='testnet'?'Verified testnet purchase':'Simulated purchase'}</p></article>`).join(''):'<p class="muted">No reviews yet. Buyers can leave feedback from Purchases.</p>'}</section></section><aside class="panel panel-body product-buy-panel"><div class="eyebrow">${esc(p.seller)}</div><h1>${esc(p.name)}</h1><div class="detail-metrics"><div><strong>${s.purchases}</strong><span>${s.paymentMode==='testnet'?'Verified purchases':'Simulated purchases'}</span></div><div><strong>${s.averageRating===null?'—':s.averageRating+' / 5'}</strong><span>${s.reviewCount} ${s.reviewCount===1?'review':'reviews'}</span></div></div><div class="price"><span>Price</span><strong>${esc(p.price)} ${esc(p.asset)}</strong></div>${p.status==='published'?'<button class="btn primary full" id="detailBuy">Buy product</button>':'<p class="notice">This product is archived and unavailable for new purchases. Existing buyers retain access under their purchase terms.</p>'}<p class="field-note">Network fees are additional. Keep your purchase pass to restore access.</p><div class="detail-divider"></div><h3>Refunds & access</h3><p class="muted small">Buyers can request a refund from Purchases and explain why. Refunds require seller approval and are not automatic or guaranteed. A completed refund ends future downloads for new purchases. Files already downloaded cannot be recalled.</p><div class="detail-divider"></div><h3>About the seller</h3><p class="muted small">${esc(data.store.bio)}</p><p class="note">Purchase totals count completed purchases, including refunded purchases, rather than unique people. ${s.paymentMode==='testnet'?'Simulation purchases are excluded.':'No funds were transferred in simulation.'}</p></aside></div>`;
 bind('detailBack',()=>browse());bind('detailBuy',()=>checkout(p.id));
}

document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkoutWatch?.refresh();});

function storeAccountAuth(register){
 app.innerHTML=`<div class="form"><div class="eyebrow">Seller account</div><h1>${register?'Create your store.':'Welcome back.'}</h1><p class="muted">${register?'Prepare your store and product drafts. Publish after your payment connector is online.':'Sign in to your private seller workspace.'}</p>${register?'<label>Store name</label><input id="storeName" maxlength="60">':''}<label>Username</label><input id="storeUser" autocomplete="username" maxlength="40"><label>Password</label><input id="storePassword" type="password" autocomplete="${register?'new-password':'current-password'}" maxlength="128"><p class="note">${register?'Use at least 14 characters. Save your credentials; password recovery is not available yet.':''}</p><button class="btn primary full" id="storeSubmit">${register?'Create store':'Sign in'}</button><button class="btn quiet full" id="storeBack">Back</button></div>`;
 bind('storeBack',seller);bind('storeSubmit',async()=>{const data=await api('/api/store-account/'+(register?'register':'login'),{username:document.querySelector('#storeUser').value,password:document.querySelector('#storePassword').value,...(register?{name:document.querySelector('#storeName').value}:{})});storeAccountPage(data);});
}
function storeAccountPage(data){
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">SELLER WORKSPACE</div><h1>${esc(data.name)}</h1><p class="sub">@${esc(data.username)} · ${data.drafts.length} product drafts</p></div><div class="actions"><button class="btn primary" id="accountProducts">Products</button><button class="btn" id="accountRefunds">Refunds & updates</button><button class="btn quiet" id="accountLogout">Sign out</button></div></div><section class="panel"><div class="panel-body"><h2>Wallet connector · ${esc(data.walletStatus)}</h2><p>${data.wallet?'Testnet wallet report received at block '+esc(String(data.wallet.height))+'.':'Connect the wallet running on your computer.'} ${data.canPublish?'Your payment connector is ready. Publish a product to accept testnet purchases. Refunds require approval in your connector terminal.':'Start the updated payment connector to enable publishing. Existing purchases remain available.'}</p><div class="actions"><button class="btn primary" id="pairWallet">${data.walletStatus==='not_connected'?'Connect wallet':'Replace connection'}</button><button class="btn" id="refreshConnection">Refresh status</button><button class="btn quiet" id="walletGuide">Setup guide</button>${data.walletStatus!=='not_connected'?'<button class="btn quiet" id="disconnectWallet">Disconnect</button>':''}</div></div></section><div class="seller-grid"><section class="panel"><div class="panel-body"><h2>Store profile</h2><label>Store name</label><input id="accountName" maxlength="60" value="${esc(data.name)}"><label>Description</label><textarea id="accountBio" maxlength="500">${esc(data.bio)}</textarea><button class="btn primary" id="accountSave">Save profile</button><h2>Product drafts</h2>${data.drafts.map(d=>`<article class="request"><h3>${esc(d.name)}</h3><p>${esc(d.description)}</p><span class="badge">Draft</span></article>`).join('')||'<p class="muted">Your first product starts here.</p>'}</div></section><aside class="panel"><div class="panel-body"><h2>Add a product draft</h2><label>Product name</label><input id="draftName" maxlength="80"><label>Description</label><textarea id="draftDescription" maxlength="1000"></textarea><button class="btn primary full" id="draftSave">Save draft</button><p class="note">Drafts are visible only in your seller workspace.</p></div></aside></div>`;
 bind('accountProducts',manageStore);bind('accountRefunds',()=>seller(true));
 bind('walletGuide',()=>walletSetupGuide());
 bind('pairWallet',async()=>{if(data.walletStatus!=='not_connected'&&!confirm('Replace the current connector credential? The previous connector will stop working.'))return;const pair=await api('/api/store-account/pair',{});walletSetupGuide(pair.token);});
 bind('refreshConnection',seller);bind('disconnectWallet',async()=>{if(confirm('Disconnect this store’s wallet connector?'))storeAccountPage(await api('/api/store-account/disconnect',{}));});
 bind('accountLogout',async()=>{await api('/api/store-account/logout',{});await seller();});
 bind('accountSave',async()=>{storeAccountPage(await api('/api/store-account/profile',{name:document.querySelector('#accountName').value,bio:document.querySelector('#accountBio').value}));toast('Store profile saved.');});
 bind('draftSave',async()=>{storeAccountPage(await api('/api/store-account/draft',{name:document.querySelector('#draftName').value,description:document.querySelector('#draftDescription').value}));toast('Product draft saved.');});
}

function walletSetupGuide(token){
 view='wallet-guide';nav();
 const command=text=>`<pre class="wallet-command"><code>${esc(text)}</code></pre>`;
 app.innerHTML=`<div class="heading"><div><div class="eyebrow">SELLER SETUP</div><h1>Connect your wallet.</h1><p class="sub">A step-by-step guide for the current Mac testnet connector.</p></div><button class="btn" id="guideBack">Back to store</button></div><section class="panel panel-body wallet-guide"><p>Already connected? Keep the connector terminal running. Opening this guide does not replace your credential.</p>
 ${token?`<h2>Your pairing credential</h2><p>Copy this into the hidden setup prompt in step 4. It is shown here once and expires in 30 days. Keep it private: it authenticates your wallet connector.</p><div class="address">${esc(token)}</div>`:''}
 <details open><summary>1. Prepare your computer</summary><p>You need Node.js 22 or newer, Python 3, Git and a working testnet zcash-devtool wallet. Keep the computer online while the connector runs. This guide uses Terminal, not the browser console.</p>${command(`node --version
python3 --version
git --version`)}<p>If you already have Veylo installed, open its folder. Otherwise clone the current project:</p>${command(`mkdir -p "$HOME/Developer"
git clone https://github.com/theeagle2407/veylo.git "$HOME/Developer/veylo"
cd "$HOME/Developer/veylo"`)}<p>For an existing Desktop installation use:</p>${command(`cd "$HOME/Desktop/veylo"`)}<p>The folder must contain scripts/setup-seller-connector.py and scripts/seller-connector.mjs. If either is missing, obtain the latest connector release before continuing.</p></details>
 <details><summary>2. Use an existing wallet or build the supplied CLI</summary><p>If your working testnet wallet is already installed, skip the build. Use its full executable path in step 4. For a fresh build, install Rust with rustup using rust-lang.org/tools/install and Apple command-line tools, then run these commands from the Veylo folder:</p>${command(`xcode-select --install
rustup toolchain install 1.97.1
bash tools/nu7-wallet/build-locked.sh`)}<p>If Apple reports the tools are already installed, continue with the remaining commands. The first Rust build can take several minutes. The supplied CLI is a patched testnet reference wallet; see tools/nu7-wallet/README.md for its pinned source and limits.</p>${command(`pwd
./tools/nu7-wallet/target/release/zcash-devtool wallet --help`)}<p>The executable path is your project folder followed by /tools/nu7-wallet/target/release/zcash-devtool.</p></details>
 <details><summary>3. Create a seller wallet, only if you need one</summary><p>Skip this step if you already have a seller wallet. For a new wallet, run from the project folder. At the mnemonic prompt, press Enter without typing to generate a new wallet. Never paste the recovery phrase into Veylo.</p>${command(`umask 077
./tools/nu7-wallet/target/release/zcash-devtool wallet -w "$HOME/veylo-seller-wallet" init --name "My store" --identity "$HOME/veylo-seller-wallet.age" --network test --server zecrocks`)}<p>Do not initialize over an existing wallet. Keep the wallet directory and age identity backed up privately. Find the account UUID:</p>${command(`./tools/nu7-wallet/target/release/zcash-devtool wallet -w "$HOME/veylo-seller-wallet" list-accounts`)}<p>The UUID identifies the account inside your wallet. It is not a receiving address. For an existing installation, substitute its executable and wallet directory in this command.</p></details>
 <details open><summary>4. Pair the store</summary><p>Choose Connect wallet in your seller workspace to generate a pairing credential. Then run from the project folder:</p>${command(`python3 scripts/setup-seller-connector.py`)}<dl><dt>Website URL</dt><dd>${esc(location.origin)}</dd><dt>Pairing credential</dt><dd>The value shown when you choose Connect wallet. Paste it at the hidden prompt; characters will not appear.</dd><dt>Wallet binary</dt><dd>The full path to your working zcash-devtool executable.</dd><dt>Wallet directory</dt><dd>The folder containing your seller wallet, not the .age identity file.</dd><dt>Account UUID</dt><dd>The account identifier from list-accounts.</dd></dl><p>No recovery phrase or private key is uploaded. For refunds, configure the path to your local .age identity using python3 scripts/enable-seller-refunds.py. The identity file stays on your computer. Settings are stored privately at ~/.veylo-connector/config.json.</p></details>
 <details open><summary>5. Start and confirm</summary>${command(`node scripts/seller-connector.mjs`)}<p>Look for “Connected to” followed by your store name. Keep this terminal running and return to the store to select Refresh status. Reports are sent approximately every 30 seconds. After 90 seconds without a report, the store shows offline.</p><p>Online with the updated payment connector enables product publishing. The connector creates invoices and reports matching wallet outputs for verification. Approve a refund in the seller console, then review the amount and destination in Terminal and type SEND. A completed refund requires ten confirmations.</p></details>
 <details><summary>6. Reconnect or troubleshoot</summary><p><strong>After a restart:</strong> run node scripts/seller-connector.mjs from the project folder. Existing credentials can be reused until they expire or are revoked.</p><p><strong>Replace a connection:</strong> stop the connector with Ctrl+C, choose Replace connection in the store, move the old local settings aside, and rerun setup with the new credential.</p>${command(`mv "$HOME/.veylo-connector/config.json" "$HOME/.veylo-connector/config-$(date +%s).json"
python3 scripts/setup-seller-connector.py
node scripts/seller-connector.mjs`)}<p><strong>Account not found:</strong> check list-accounts for the selected wallet. <strong>Wallet check failed:</strong> run the wallet get-info command locally and check network compatibility. <strong>Website rejected connection:</strong> check the website URL, pairing expiry, and whether the Veylo backend and tunnel are online.</p><p>Disconnect revokes the pairing credential. It does not delete your wallet, move funds or cancel a blockchain transaction. Do not share config.json in screenshots or commit it to Git.</p></details></section>`;
 bind('guideBack',seller);
}
